// 2026-11-13 每日巡檢：Issue #24 理事長往生、會員代表大會 vs 會員大會、年度工作計畫要不要送縣府
const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
 ['理事長往生','一個月內補選'],['理事長死了怎麼辦','一個月內補選'],['理事長過世了要怎麼辦','一個月內補選'],['理事長出缺怎麼辦','一個月內補選'],['我們協會理事長身故','一個月內補選'],
 ['會員代表大會跟會員大會差在哪','三百人'],['會員代表大會和會員大會有什麼不同','三百人'],['會員大會與會員代表大會的差別','三百人'],
 ['年度工作計畫要送縣府嗎','報請主管機關備查'],['工作計畫要報縣府嗎','報請主管機關備查'],['協會的年度計畫需要送社會處備查嗎','報請主管機關備查'],
];
const no=['理事長辭職要補選嗎','理事長剩半年出缺','副理事長過世','會員過世怎麼辦','會員過世委託書還能用嗎','合作社理事主席過世','公會理事長過世','理事長改選後銀行要變更嗎','常年會跟會員大會一樣嗎','什麼是會員代表大會','社區年度計畫什麼時候要送','補助計畫要送哪裡','預算要送縣府嗎','理事長任期幾年','會員代表大會要幾天前通知'];
const mine=/(理事長過世（出缺）|會員代表大會是會員超過300人時|年度工作計畫要送：)/;
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const txt=a?(a.title+a.summary):'';if(!a||!mine.test(a.title)||!txt.includes(e)||!a.direct){bad++;console.log('✗',q,a&&a.title)}});
no.forEach(q=>{const a=A(q);if(a&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
